      <div className="flex items-center justify-between"><Link href="/" className="flex items-center gap-3" data-testid="link-brand"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))]"><GraduationCap size={20} /></span><span className="font-display text-lg font-semibold">Attendex Tracker</span></Link><button className="rounded-lg p-2 md:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X size={18} /></button></div>
