function AuthLayout({ children, title, detail }: { children: ReactNode; title: string; detail: string }) {
  return <div className="grain min-h-[100dvh] bg-[hsl(var(--primary))] p-5 text-primary-foreground md:p-10"><div className="mx-auto grid min-h-[calc(100dvh-2.5rem)] max-w-6xl overflow-hidden rounded-[2rem] bg-background text-foreground shadow-2xl md:grid-cols-[.9fr_1.1fr]"><div className="relative hidden overflow-hidden bg-[hsl(var(--sidebar))] p-10 text-[hsl(var(--sidebar-foreground))] md:flex md:flex-col md:justify-between"><Link href="/" className="flex items-center gap-3" data-testid="link-auth-brand"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><GraduationCap size={22} /></span><span className="font-display text-xl font-semibold">Attendex Tracker</span></Link><div className="relative"><div className="absolute -left-10 -top-28 h-64 w-64 rounded-full border border-[hsl(var(--sidebar-foreground)/.15)]" /><div className="absolute -bottom-28 right-0 h-72 w-72 rounded-full border border-[hsl(var(--accent)/.32)]" /><p className="relative max-w-sm font-display text-4xl leading-[1.08]">Turn attendance into your academic advantage.</p><p className="relative mt-5 max-w-xs text-sm leading-6 text-[hsl(var(--sidebar-foreground)/.65)]">Plan smarter, protect your attendance, and keep your semester moving with confidence.</p></div><p className="text-xs text-[hsl(var(--sidebar-foreground)/.45)]">Show up with intention. Finish with momentum.</p></div><div className="flex items-center p-6 sm:p-12"><div className="mx-auto w-full max-w-md enter"><p className="text-xs font-bold uppercase tracking-[.18em] text-[hsl(var(--destructive))]">Attendex / {title.toLowerCase()}</p><h1 className="mt-4 font-display text-4xl font-semibold tracking-tight sm:text-5xl">{title}</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">{detail}</p>{children}</div></div></div></div>;
}

function LoginPage() {
  const [, setLocation] = useLocation();
  const qc = useQueryClient();
  const login = useLogin();
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); setError(''); login.mutate({ data: form }, { onSuccess: (result) => { qc.setQueryData(getGetCurrentStudentQueryKey(), result.student); setLocation('/'); }, onError: (err) => setError(errorMessage(err)) }); };
  return <AuthLayout title="Welcome back." detail="Your classes have changed since the last visit. Let’s pick up the thread."><form onSubmit={submit} className="mt-8 space-y-5"><Field label="Email"><input required autoComplete="email" type="email" className={inputClass()} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@college.edu" data-testid="input-email" /></Field><Field label="Password"><input required autoComplete="current-password" type="password" className={inputClass()} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="At least 8 characters" data-testid="input-password" /></Field><div className="flex justify-end"><Link href="/forgot-password" className="text-sm font-semibold text-[hsl(var(--destructive))] hover:underline" data-testid="link-forgot-password">Forgot password?</Link></div>{error && <p className="rounded-xl bg-[hsl(var(--destructive)/.1)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-login-error">{error}</p>}<Button type="submit" className="w-full" disabled={login.isPending} testId="button-submit-login">{login.isPending ? 'Signing you in…' : 'Sign in'} <ArrowRight size={16} /></Button></form><p className="mt-8 text-center text-sm text-muted-foreground">New to Attendex? <Link href="/signup" className="font-semibold text-foreground underline decoration-[hsl(var(--accent))] decoration-2 underline-offset-4" data-testid="link-signup">Create an account</Link></p></AuthLayout>;
}

function ForgotPasswordPage() {
  const [, setLocation] = useLocation();
  const request = useRequestPasswordReset();
  const confirm = useConfirmPasswordReset();
  const [step, setStep] = useState<'email' | 'code'>('email');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [debugOtp, setDebugOtp] = useState('');

  const requestCode = (event: FormEvent) => {
    event.preventDefault();
    setError('');
    setNotice('');
    request.mutate({ data: { email } }, {
      onSuccess: (result) => {
        setStep('code');
        setDebugOtp(result.debugOtp || '');
        setNotice('If an account exists for that email, your OTP is on its way.');
      },
      onError: (err) => setError(errorMessage(err)),
    });
  };

  const resetPassword = (event: FormEvent) => {
    event.preventDefault();
    setError('');
    confirm.mutate({ data: { email, otp, newPassword } }, {
      onSuccess: () => {
        setLocation('/login');
      },
      onError: (err) => setError(errorMessage(err)),
    });
  };

  return <AuthLayout title={step === 'email' ? 'Reset your password.' : 'Choose a fresh password.'} detail={step === 'email' ? 'Enter your account email and we’ll send a six-digit code to help you get back in.' : 'Your code is valid for 10 minutes. Choose something you can remember and no one else can guess.'}>
    {step === 'email' ? <form onSubmit={requestCode} className="mt-8 space-y-5">
      <Field label="Account email"><input required autoComplete="email" type="email" className={inputClass()} value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@college.edu" data-testid="input-reset-email" /></Field>
      {error && <p className="rounded-xl bg-[hsl(var(--destructive)/.1)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-reset-error">{error}</p>}
      <Button type="submit" className="w-full" disabled={request.isPending} testId="button-request-reset">{request.isPending ? 'Sending code…' : 'Send reset code'} <ArrowRight size={16} /></Button>
    </form> : <form onSubmit={resetPassword} className="mt-8 space-y-5">
      {notice && <p className="rounded-xl bg-[hsl(168_37%_82%/.35)] p-3 text-sm text-[hsl(var(--primary))]" data-testid="status-reset-sent">{notice}</p>}
      {debugOtp && <p className="rounded-xl border border-[hsl(var(--accent)/.45)] bg-[hsl(var(--accent)/.12)] p-3 text-sm text-[hsl(var(--accent-foreground))]" data-testid="status-reset-debug">Preview OTP: <span className="font-data font-bold tracking-[.2em]">{debugOtp}</span></p>}
      <Field label="6-digit OTP"><input required inputMode="numeric" pattern="[0-9]{6}" minLength={6} maxLength={6} className={`${inputClass()} font-data tracking-[.3em]`} value={otp} onChange={(event) => setOtp(event.target.value.replace(/\D/g, '').slice(0, 6))} placeholder="000000" data-testid="input-reset-otp" /></Field>
      <Field label="New password"><input required minLength={8} autoComplete="new-password" type="password" className={inputClass()} value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="At least 8 characters" data-testid="input-reset-new-password" /></Field>
      {error && <p className="rounded-xl bg-[hsl(var(--destructive)/.1)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-reset-error">{error}</p>}
      <Button type="submit" className="w-full" disabled={confirm.isPending} testId="button-confirm-reset">{confirm.isPending ? 'Updating password…' : 'Set new password'} <Check size={16} /></Button>
      <button type="button" className="w-full text-sm font-semibold text-muted-foreground hover:text-foreground" onClick={() => { setStep('email'); setError(''); setDebugOtp(''); }} data-testid="button-resend-reset">Use a different email or resend</button>
    </form>}
    <p className="mt-8 text-center text-sm text-muted-foreground">Remembered your password? <Link href="/login" className="font-semibold text-foreground underline decoration-[hsl(var(--accent))] decoration-2 underline-offset-4" data-testid="link-back-to-login">Back to sign in</Link></p>
  </AuthLayout>;
}

function SignupPage() {
  const [, setLocation] = useLocation();
  const qc = useQueryClient();
  const signup = useSignup();
  const [error, setError] = useState('');
  const [form, setForm] = useState({ name: '', email: '', password: '', college: '', course: '', year: '' });
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); setError(''); signup.mutate({ data: { ...form, year: form.year ? Number(form.year) : undefined } }, { onSuccess: (result) => { qc.setQueryData(getGetCurrentStudentQueryKey(), result.student); setLocation('/'); }, onError: (err) => setError(errorMessage(err)) }); };
  return <AuthLayout title="Make room for progress." detail="Set up your student profile once. We’ll use it to make the daily view feel like yours."><form onSubmit={submit} className="mt-7 grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Your name"><input required autoComplete="name" minLength={2} className={inputClass()} value={form.name} onChange={(e) => update('name', e.target.value)} placeholder="Alex Morgan" data-testid="input-signup-name" /></Field></div><div className="sm:col-span-2"><Field label="Email"><input required autoComplete="email" type="email" className={inputClass()} value={form.email} onChange={(e) => update('email', e.target.value)} placeholder="you@college.edu" data-testid="input-signup-email" /></Field></div><Field label="Password"><input required autoComplete="new-password" minLength={8} type="password" className={inputClass()} value={form.password} onChange={(e) => update('password', e.target.value)} placeholder="8+ characters" data-testid="input-signup-password" /></Field><Field label="Year"><select className={inputClass()} value={form.year} onChange={(e) => update('year', e.target.value)} data-testid="select-signup-year"><option value="">Select year</option>{[1, 2, 3, 4, 5, 6, 7, 8].map((year) => <option key={year} value={year}>{year === 1 ? 'First' : year === 2 ? 'Second' : year === 3 ? 'Third' : year === 4 ? 'Fourth' : `${year}th`} year</option>)}</select></Field><div className="sm:col-span-2"><Field label="College" hint="Optional for now"><input className={inputClass()} value={form.college} onChange={(e) => update('college', e.target.value)} placeholder="Northbridge College" data-testid="input-signup-college" /></Field></div><div className="sm:col-span-2"><Field label="Course" hint="Optional for now"><input className={inputClass()} value={form.course} onChange={(e) => update('course', e.target.value)} placeholder="Psychology" data-testid="input-signup-course" /></Field></div>{error && <p className="sm:col-span-2 rounded-xl bg-[hsl(var(--destructive)/.1)] p-3 text-sm text-[hsl(var(--destructive))]" data-testid="status-signup-error">{error}</p>}<div className="sm:col-span-2"><Button type="submit" className="w-full" disabled={signup.isPending} testId="button-submit-signup">{signup.isPending ? 'Creating your space…' : 'Create my space'} <ArrowRight size={16} /></Button></div></form><p className="mt-7 text-center text-sm text-muted-foreground">Already have an account? <Link href="/login" className="font-semibold text-foreground underline decoration-[hsl(var(--accent))] decoration-2 underline-offset-4" data-testid="link-login">Sign in</Link></p></AuthLayout>;
}

function StatCard({ label, value, detail, icon: Icon, accent = 'accent' }: { label: string; value: string | number; detail: string; icon: LucideIcon; accent?: 'accent' | 'coral' | 'teal' }) {
  const color = accent === 'coral' ? 'bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]' : accent === 'teal' ? 'bg-[hsl(168_37%_82%)] text-[hsl(var(--primary))]' : 'bg-[hsl(var(--accent)/.2)] text-[hsl(var(--accent-foreground))]';
  return <div className="rounded-2xl border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg hover:shadow-[hsl(var(--primary)/.05)]" data-testid={`card-stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">{label}</span><span className={`flex h-9 w-9 items-center justify-center rounded-xl ${color}`}><Icon size={17} /></span></div><p className="mt-5 font-display text-3xl font-semibold">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>;
}

function DashboardPage() {
  const dashboard = useGetDashboard();
  const recommendation = useGetRecommendation();
  if (dashboard.isLoading) return <LoadingPage />;
  if (dashboard.isError || !dashboard.data) return <QueryError retry={() => dashboard.refetch()} message={errorMessage(dashboard.error)} />;
  const data = dashboard.data;
  const rec = recommendation.data;
  const firstName = data.student.name.split(' ')[0];
  return <div className="space-y-7">
    <section className="enter flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-sm font-semibold text-[hsl(var(--destructive))]">Good morning, {firstName}.</p><h1 className="mt-1 font-display text-4xl font-semibold tracking-tight md:text-5xl">Keep the thread going.</h1><p className="mt-2 text-sm text-muted-foreground">{formatDate(todayISO())} <span className="mx-2 text-[hsl(var(--border))]">/</span> {data.streak > 0 ? `${data.streak}-day study streak` : 'A fresh start today'}</p></div><Link href="/study" className="inline-flex items-center gap-2 self-start rounded-full border bg-card px-4 py-2.5 text-sm font-semibold transition hover:border-[hsl(var(--accent))] hover:bg-[hsl(var(--accent)/.1)] md:self-auto" data-testid="link-log-study"><Clock3 size={16} /> Log a study session <ArrowRight size={15} /></Link></section>
    {rec && <section className="enter-2 relative overflow-hidden rounded-3xl bg-[hsl(var(--primary))] p-6 text-primary-foreground md:p-8"><div className="absolute -right-16 -top-24 h-64 w-64 rounded-full border border-[hsl(var(--accent)/.22)]" /><div className="absolute -bottom-32 right-24 h-52 w-52 rounded-full border border-[hsl(var(--sidebar-foreground)/.1)]" /><div className="relative flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="max-w-xl"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.16em] text-[hsl(var(--accent))]"><Sparkles size={14} /> Your next best move</div><h2 className="mt-3 font-display text-2xl font-semibold">{rec.title}</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--sidebar-foreground)/.7)]">{rec.reason}</p></div><Link href={rec.tone === 'study' ? '/study' : rec.tone === 'task' ? '/tasks' : rec.tone === 'exam' ? '/exams' : '/subjects'} className="relative inline-flex shrink-0 items-center justify-center gap-2 rounded-full bg-[hsl(var(--accent))] px-5 py-3 text-sm font-bold text-[hsl(var(--accent-foreground))] transition hover:translate-x-0.5" data-testid="link-recommendation-action">{rec.action} <ArrowRight size={15} /></Link></div></section>}
    <section className="enter-3 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Attendance health" value={`${Math.round(data.attendance.percentage)}%`} detail={`${data.attendance.attended} of ${data.attendance.total} classes attended`} icon={Radar} accent="teal" /><StatCard label="Productivity" value={`${data.productivity}%`} detail="Across your recent work" icon={Target} /><StatCard label="Study momentum" value={`${data.study.minutesThisWeek}m`} detail={`${data.study.sessionsThisWeek} sessions this week`} icon={TrendingUp} accent="coral" /><StatCard label="Open tasks" value={data.tasks.open} detail={`${data.tasks.dueToday} due today · ${data.tasks.completed} completed`} icon={CheckCircle2} /></section>
    <section className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><div className="rounded-2xl border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">Next on your calendar</p><h2 className="mt-1 font-display text-2xl font-semibold">Upcoming exams</h2></div><Link href="/exams" className="text-sm font-semibold text-[hsl(var(--destructive))]" data-testid="link-view-exams">View all</Link></div>{data.exams.next ? <div className="mt-6 flex items-center gap-4 rounded-2xl bg-[hsl(var(--muted)/.55)] p-4"><div className="flex h-14 w-14 shrink-0 flex-col items-center justify-center rounded-xl bg-[hsl(var(--destructive))] text-primary-foreground"><span className="text-[10px] font-bold uppercase">{new Intl.DateTimeFormat('en-US', { month: 'short' }).format(new Date(`${data.exams.next.date}T12:00:00`))}</span><span className="font-display text-xl font-semibold">{new Date(`${data.exams.next.date}T12:00:00`).getDate()}</span></div><div className="min-w-0"><p className="font-semibold">{data.exams.next.title}</p><p className="mt-1 text-sm text-muted-foreground">{data.exams.next.subjectName || 'General exam'} {data.exams.next.room ? `· ${data.exams.next.room}` : ''}</p></div><span className="ml-auto hidden text-right text-xs text-muted-foreground sm:block">{shortDate(data.exams.next.date)}<br />{data.exams.next.time || 'Time to be announced'}</span></div> : <EmptyState icon={CalendarDays} title="Your calendar is clear" detail="Add an exam when a date lands so it can shape your daily plan." action={<Link href="/exams" className="text-sm font-bold text-[hsl(var(--destructive))]" data-testid="link-add-first-exam">Add an exam</Link>} />}</div><div className="rounded-2xl border bg-[hsl(var(--accent)/.16)] p-6"><div className="flex items-center gap-2 text-[hsl(var(--accent-foreground))]"><Flame size={18} /><span className="text-xs font-bold uppercase tracking-[.14em]">Keep the spark</span></div><p className="mt-5 font-display text-5xl font-semibold">{data.streak}</p><p className="mt-1 text-sm font-semibold">day study streak</p><p className="mt-5 text-sm leading-6 text-muted-foreground">Small, repeatable sessions are how momentum compounds. Show up for one focused block today.</p><Link href="/study" className="mt-5 inline-flex items-center gap-2 text-sm font-bold" data-testid="link-streak-study">Open study log <ArrowRight size={14} /></Link></div></section>
    <section className="rounded-2xl border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">Your trail</p><h2 className="mt-1 font-display text-2xl font-semibold">Recent activity</h2></div><ActivityIcon size={20} className="text-muted-foreground" /></div><div className="mt-5 grid gap-3 md:grid-cols-2">{data.recentActivity?.length ? data.recentActivity.map((item, index) => <div className="flex items-center gap-3 rounded-xl border bg-background/45 p-3" key={`${item.label}-${index}`} data-testid={`activity-${index}`}><span className={`h-2.5 w-2.5 rounded-full ${item.tone === 'amber' ? 'bg-[hsl(var(--accent))]' : item.tone === 'green' ? 'bg-[hsl(168_37%_48%)]' : item.tone === 'violet' ? 'bg-[hsl(240_35%_62%)]' : 'bg-[hsl(var(--destructive))]'}`} /><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{item.label}</span><span className="block text-xs text-muted-foreground">{item.detail}</span></span></div>) : <p className="text-sm text-muted-foreground">Your activity will appear here as you make progress.</p>}</div></section>
  </div>;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[hsl(var(--foreground)/.4)] p-0 backdrop-blur-sm sm:items-center sm:p-5"><div className="max-h-[90dvh] w-full max-w-lg overflow-auto rounded-t-3xl border bg-card p-6 shadow-2xl sm:rounded-3xl"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-semibold">{title}</h2><button onClick={onClose} className="rounded-full p-2 text-muted-foreground hover:bg-muted" data-testid="button-close-modal"><X size={18} /></button></div>{children}</div></div>;
}
function PageHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[hsl(var(--destructive))]">{eyebrow}</p><h1 className="mt-2 font-display text-4xl font-semibold tracking-tight">{title}</h1><p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{detail}</p></div>{action}</div>;
}

function SubjectsPage() {
  const subjects = useGetSubjects();
  const attendance = useGetAttendance();
  const create = useCreateSubject(); const update = useUpdateSubject(); const remove = useDeleteSubject(); const mark = useCreateAttendance();
  const qc = useQueryClient(); const [modal, setModal] = useState<Subject | 'new' | null>(null); const [attendModal, setAttendModal] = useState<Subject | null>(null);
  const refresh = () => { qc.invalidateQueries({ queryKey: getGetSubjectsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAttendanceQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); };
  const [form, setForm] = useState<SubjectInput>({ name: '', code: '', color: subjectColors[0], attended: 0, total: 0 });
  const openForm = (subject?: Subject) => { setForm(subject ? { name: subject.name, code: subject.code, color: subject.color, attended: subject.attended, total: subject.total } : { name: '', code: '', color: subjectColors[(subjects.data?.length || 0) % subjectColors.length], attended: 0, total: 0 }); setModal(subject || 'new'); };
  const submit = (event: FormEvent) => { event.preventDefault(); if (modal === 'new') create.mutate({ data: form }, { onSuccess: () => { refresh(); setModal(null); } }); else if (modal) update.mutate({ id: modal.id, data: form }, { onSuccess: () => { refresh(); setModal(null); } }); };
  const deleteItem = (subject: Subject) => { if (window.confirm(`Remove ${subject.name}?`)) remove.mutate({ id: subject.id }, { onSuccess: refresh }); };
  const markAttendance = (event: FormEvent) => { event.preventDefault(); if (!attendModal) return; const formEl = event.currentTarget as HTMLFormElement; const values = new FormData(formEl); mark.mutate({ data: { subjectId: attendModal.id, date: String(values.get('date')), present: values.get('present') === 'true' } }, { onSuccess: () => { refresh(); setAttendModal(null); } }); };
  if (subjects.isLoading) return <LoadingPage />; if (subjects.isError) return <QueryError retry={() => subjects.refetch()} />;
  return <div className="space-y-7"><PageHeading eyebrow="The classes that shape your week" title="Subjects" detail="Keep an honest pulse on attendance, without turning it into a spreadsheet." action={<Button onClick={() => openForm()} testId="button-add-subject"><Plus size={16} /> Add subject</Button>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{subjects.data?.length ? subjects.data.map((subject) => <div className="group rounded-2xl border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg hover:shadow-[hsl(var(--primary)/.05)]" key={subject.id} data-testid={`card-subject-${subject.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: subject.color }} /><span className="font-data text-xs font-semibold text-muted-foreground">{subject.code}</span></div><div className="flex gap-1 opacity-100 sm:opacity-0 sm:transition sm:group-hover:opacity-100"><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" onClick={() => openForm(subject)} data-testid={`button-edit-subject-${subject.id}`}><Pencil size={14} /></button><button className="rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--destructive)/.1)] hover:text-[hsl(var(--destructive))]" onClick={() => deleteItem(subject)} data-testid={`button-delete-subject-${subject.id}`}><Trash2 size={14} /></button></div></div><h2 className="mt-5 font-display text-xl font-semibold">{subject.name}</h2><div className="mt-5 flex items-end justify-between"><div><span className="font-display text-4xl font-semibold">{Math.round(subject.percentage)}%</span><span className="ml-2 text-xs text-muted-foreground">attendance</span></div><Button variant="secondary" className="px-3 py-2 text-xs" onClick={() => setAttendModal(subject)} testId={`button-mark-attendance-${subject.id}`}>Mark class</Button></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full transition-all" style={{ width: `${Math.min(subject.percentage, 100)}%`, backgroundColor: subject.color }} /></div><p className="mt-2 text-xs text-muted-foreground">{subject.attended} present of {subject.total} recorded</p></div>) : <div className="md:col-span-2 xl:col-span-3"><EmptyState icon={BookOpen} title="Start with your first subject" detail="Add the classes on your timetable, then let attendance become a useful signal instead of a worry." action={<Button onClick={() => openForm()} testId="button-add-first-subject"><Plus size={16} /> Add subject</Button>} /></div>}</div><div className="rounded-2xl border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">Attendance trail</p><h2 className="mt-1 font-display text-2xl font-semibold">Recent classes</h2></div><span className="font-data text-xs text-muted-foreground">{attendance.data?.length || 0} records</span></div><div className="mt-5 grid gap-2 md:grid-cols-2">{attendance.data?.slice(0, 8).map((item) => <div key={item.id} className="flex items-center justify-between rounded-xl bg-muted/50 px-4 py-3" data-testid={`attendance-record-${item.id}`}><span><span className="block text-sm font-semibold">{item.subjectName || 'Subject'}</span><span className="text-xs text-muted-foreground">{formatDate(item.date)}</span></span><span className={`rounded-full px-3 py-1 text-xs font-bold ${item.present ? 'bg-[hsl(168_37%_82%)] text-[hsl(var(--primary))]' : 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))]'}`}>{item.present ? 'Present' : 'Absent'}</span></div>)}</div></div>{modal && <Modal title={modal === 'new' ? 'Add a subject' : 'Edit subject'} onClose={() => setModal(null)}><form className="mt-6 space-y-4" onSubmit={submit}><Field label="Subject name"><input required className={inputClass()} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Research methods" data-testid="input-subject-name" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Course code"><input required className={inputClass()} value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="PSY-204" data-testid="input-subject-code" /></Field><Field label="Color"><input type="color" className={`${inputClass()} h-12 p-1`} value={form.color} onChange={(e) => setForm({ ...form, color: e.target.value })} data-testid="input-subject-color" /></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Present"><input type="number" min="0" className={inputClass()} value={form.attended} onChange={(e) => setForm({ ...form, attended: Number(e.target.value) })} data-testid="input-subject-attended" /></Field><Field label="Total classes"><input type="number" min="0" className={inputClass()} value={form.total} onChange={(e) => setForm({ ...form, total: Number(e.target.value) })} data-testid="input-subject-total" /></Field></div><Button type="submit" className="w-full" disabled={create.isPending || update.isPending} testId="button-save-subject"><Check size={16} /> Save subject</Button></form></Modal>}{attendModal && <Modal title={`Mark ${attendModal.name}`} onClose={() => setAttendModal(null)}><form className="mt-6 space-y-4" onSubmit={markAttendance}><Field label="Class date"><input required type="date" name="date" defaultValue={todayISO()} className={inputClass()} data-testid="input-attendance-date" /></Field><Field label="Were you there?"><select name="present" className={inputClass()} defaultValue="true" data-testid="select-attendance-present"><option value="true">Present</option><option value="false">Absent</option></select></Field><Button type="submit" className="w-full" disabled={mark.isPending} testId="button-save-attendance"><Check size={16} /> Record attendance</Button></form></Modal>}</div>;
}

function TasksPage() {
  const tasks = useGetTasks(); const subjects = useGetSubjects(); const create = useCreateTask(); const update = useUpdateTask(); const remove = useDeleteTask(); const qc = useQueryClient(); const [modal, setModal] = useState<Task | 'new' | null>(null); const [filter, setFilter] = useState('all'); const [form, setForm] = useState<TaskInput>({ title: '', description: '', status: 'todo', priority: 'medium', dueDate: '', subjectId: undefined });
  const refresh = () => { qc.invalidateQueries({ queryKey: getGetTasksQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); };
  const openForm = (task?: Task) => { setForm(task ? { title: task.title, description: task.description || '', status: task.status, priority: task.priority, dueDate: task.dueDate || '', subjectId: task.subjectId || undefined } : { title: '', description: '', status: 'todo', priority: 'medium', dueDate: '', subjectId: undefined }); setModal(task || 'new'); };
  const submit = (event: FormEvent) => { event.preventDefault(); const data = { ...form, subjectId: form.subjectId || undefined, dueDate: form.dueDate || undefined }; if (modal === 'new') create.mutate({ data }, { onSuccess: () => { refresh(); setModal(null); } }); else if (modal) update.mutate({ id: modal.id, data }, { onSuccess: () => { refresh(); setModal(null); } }); };
  const deleteItem = (task: Task) => { if (window.confirm(`Delete ${task.title}?`)) remove.mutate({ id: task.id }, { onSuccess: refresh }); };
  const filtered = tasks.data?.filter((task) => filter === 'all' || task.status === filter) || [];
  if (tasks.isLoading) return <LoadingPage />; if (tasks.isError) return <QueryError retry={() => tasks.refetch()} />;
  return <div className="space-y-7"><PageHeading eyebrow="A lighter way to hold the list" title="Tasks" detail="Move one meaningful thing forward at a time. The rest can wait its turn." action={<Button onClick={() => openForm()} testId="button-add-task"><Plus size={16} /> Add task</Button>} /><div className="flex flex-wrap gap-2">{[['all', 'All work'], ['todo', 'To do'], ['in_progress', 'In progress'], ['done', 'Done']].map(([value, label]) => <button key={value} onClick={() => setFilter(value)} className={`rounded-full px-4 py-2 text-sm font-semibold transition ${filter === value ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:text-foreground'}`} data-testid={`button-filter-${value}`}>{label}</button>)}</div>{filtered.length ? <div className="space-y-3">{filtered.map((task) => <div key={task.id} className="group flex flex-col gap-4 rounded-2xl border bg-card p-5 transition hover:border-[hsl(var(--accent))] sm:flex-row sm:items-center" data-testid={`card-task-${task.id}`}><button onClick={() => update.mutate({ id: task.id, data: { status: task.status === 'done' ? 'todo' : 'done' } }, { onSuccess: refresh })} className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 ${task.status === 'done' ? 'border-[hsl(168_37%_48%)] bg-[hsl(168_37%_48%)] text-white' : 'border-[hsl(var(--border))] hover:border-[hsl(var(--accent))]'}`} data-testid={`button-complete-task-${task.id}`}>{task.status === 'done' && <Check size={13} />}</button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className={`font-semibold ${task.status === 'done' ? 'text-muted-foreground line-through' : ''}`}>{task.title}</h2><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${task.priority === 'high' ? 'bg-[hsl(var(--destructive)/.11)] text-[hsl(var(--destructive))]' : task.priority === 'medium' ? 'bg-[hsl(var(--accent)/.18)] text-[hsl(var(--accent-foreground))]' : 'bg-muted text-muted-foreground'}`}>{task.priority}</span></div><p className="mt-1 line-clamp-1 text-sm text-muted-foreground">{task.description || 'No description'}</p><div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">{task.subjectName && <span className="rounded-full bg-muted px-2.5 py-1">{task.subjectName}</span>}<span className={task.dueDate && task.dueDate < todayISO() && task.status !== 'done' ? 'font-bold text-[hsl(var(--destructive))]' : ''}>{task.dueDate ? `Due ${shortDate(task.dueDate)}` : 'No due date'}</span></div></div><div className="flex gap-1 sm:opacity-0 sm:transition sm:group-hover:opacity-100"><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" onClick={() => openForm(task)} data-testid={`button-edit-task-${task.id}`}><Pencil size={15} /></button><button className="rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--destructive)/.1)] hover:text-[hsl(var(--destructive))]" onClick={() => deleteItem(task)} data-testid={`button-delete-task-${task.id}`}><Trash2 size={15} /></button></div></div>)}</div> : <EmptyState icon={CheckCircle2} title={filter === 'all' ? 'Your list is clear' : 'Nothing in this lane'} detail={filter === 'all' ? 'Add the next small assignment, reading, or errand you want out of your head.' : 'Try another status or add a new task.'} action={<Button onClick={() => openForm()} testId="button-add-first-task"><Plus size={16} /> Add a task</Button>} />}{modal && <Modal title={modal === 'new' ? 'Add a task' : 'Edit task'} onClose={() => setModal(null)}><form className="mt-6 space-y-4" onSubmit={submit}><Field label="Task title"><input required className={inputClass()} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Outline chapter three" data-testid="input-task-title" /></Field><Field label="Description"><textarea className={`${inputClass()} min-h-24 resize-y`} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="What does done look like?" data-testid="textarea-task-description" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Status"><select className={inputClass()} value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as TaskInput['status'] })} data-testid="select-task-status"><option value="todo">To do</option><option value="in_progress">In progress</option><option value="done">Done</option></select></Field><Field label="Priority"><select className={inputClass()} value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value as TaskInput['priority'] })} data-testid="select-task-priority"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Due date"><input type="date" className={inputClass()} value={form.dueDate} onChange={(e) => setForm({ ...form, dueDate: e.target.value })} data-testid="input-task-due-date" /></Field><Field label="Subject"><select className={inputClass()} value={form.subjectId || ''} onChange={(e) => setForm({ ...form, subjectId: e.target.value ? Number(e.target.value) : undefined })} data-testid="select-task-subject"><option value="">No subject</option>{subjects.data?.map((subject) => <option value={subject.id} key={subject.id}>{subject.name}</option>)}</select></Field></div><Button type="submit" className="w-full" disabled={create.isPending || update.isPending} testId="button-save-task"><Check size={16} /> Save task</Button></form></Modal>}</div>;
}

function ExamsPage() {
  const exams = useGetExams(); const subjects = useGetSubjects(); const create = useCreateExam(); const update = useUpdateExam(); const remove = useDeleteExam(); const qc = useQueryClient(); const [modal, setModal] = useState<Exam | 'new' | null>(null); const [form, setForm] = useState<ExamInput>({ title: '', date: '', time: '', room: '', notes: '', subjectId: undefined });
  const refresh = () => { qc.invalidateQueries({ queryKey: getGetExamsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); };
  const openForm = (exam?: Exam) => { setForm(exam ? { title: exam.title, date: exam.date, time: exam.time || '', room: exam.room || '', notes: exam.notes || '', subjectId: exam.subjectId || undefined } : { title: '', date: '', time: '', room: '', notes: '', subjectId: undefined }); setModal(exam || 'new'); };
  const submit = (event: FormEvent) => { event.preventDefault(); const data = { ...form, time: form.time || undefined, room: form.room || undefined, notes: form.notes || undefined, subjectId: form.subjectId || undefined }; if (modal === 'new') create.mutate({ data }, { onSuccess: () => { refresh(); setModal(null); } }); else if (modal) update.mutate({ id: modal.id, data }, { onSuccess: () => { refresh(); setModal(null); } }); };
  const deleteItem = (exam: Exam) => { if (window.confirm(`Delete ${exam.title}?`)) remove.mutate({ id: exam.id }, { onSuccess: refresh }); };
  if (exams.isLoading) return <LoadingPage />; if (exams.isError) return <QueryError retry={() => exams.refetch()} />;
  const sorted = [...(exams.data || [])].sort((a, b) => a.date.localeCompare(b.date));
  return <div className="space-y-7"><PageHeading eyebrow="Dates worth making space for" title="Exams" detail="See what’s ahead, then give each assessment the attention it deserves." action={<Button onClick={() => openForm()} testId="button-add-exam"><Plus size={16} /> Add exam</Button>} />{sorted.length ? <div className="grid gap-4 lg:grid-cols-2">{sorted.map((exam, index) => <div key={exam.id} className={`group relative overflow-hidden rounded-2xl border bg-card p-6 ${index === 0 ? 'border-[hsl(var(--accent))] shadow-lg shadow-[hsl(var(--accent)/.08)]' : ''}`} data-testid={`card-exam-${exam.id}`}><div className="absolute right-0 top-0 h-28 w-28 rounded-bl-[5rem] bg-[hsl(var(--accent)/.12)]" /><div className="relative flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-14 w-14 flex-col items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-primary-foreground"><span className="text-[10px] font-bold uppercase">{new Intl.DateTimeFormat('en-US', { month: 'short' }).format(new Date(`${exam.date}T12:00:00`))}</span><span className="font-display text-xl">{new Date(`${exam.date}T12:00:00`).getDate()}</span></div><div><span className="text-xs font-bold uppercase tracking-[.12em] text-[hsl(var(--destructive))]">{exam.status === 'completed' ? 'Completed' : index === 0 ? 'Next up' : 'Upcoming'}</span><h2 className="mt-1 font-display text-xl font-semibold">{exam.title}</h2></div></div><div className="flex gap-1 opacity-100 sm:opacity-0 sm:transition sm:group-hover:opacity-100"><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted" onClick={() => openForm(exam)} data-testid={`button-edit-exam-${exam.id}`}><Pencil size={15} /></button><button className="rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--destructive)/.1)] hover:text-[hsl(var(--destructive))]" onClick={() => deleteItem(exam)} data-testid={`button-delete-exam-${exam.id}`}><Trash2 size={15} /></button></div></div><div className="relative mt-5 grid grid-cols-2 gap-3 text-sm"><div><span className="block text-xs text-muted-foreground">When</span><span className="mt-1 block font-semibold">{formatDate(exam.date)}</span></div><div><span className="block text-xs text-muted-foreground">Where</span><span className="mt-1 block font-semibold">{exam.room || 'Room TBD'}</span></div></div>{exam.subjectName && <span className="relative mt-5 inline-flex rounded-full bg-muted px-3 py-1.5 text-xs font-semibold">{exam.subjectName}</span>}{exam.notes && <p className="relative mt-4 border-t pt-4 text-sm leading-6 text-muted-foreground">{exam.notes}</p>}</div>)}</div> : <EmptyState icon={CalendarDays} title="No exams on the horizon" detail="Put the next important date here and your dashboard will help you work backwards from it." action={<Button onClick={() => openForm()} testId="button-add-first-exam"><Plus size={16} /> Add an exam</Button>} />}{modal && <Modal title={modal === 'new' ? 'Add an exam' : 'Edit exam'} onClose={() => setModal(null)}><form onSubmit={submit} className="mt-6 space-y-4"><Field label="Exam title"><input required className={inputClass()} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Cognitive psychology midterm" data-testid="input-exam-title" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Date"><input required type="date" className={inputClass()} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} data-testid="input-exam-date" /></Field><Field label="Time"><input type="time" className={inputClass()} value={form.time} onChange={(e) => setForm({ ...form, time: e.target.value })} data-testid="input-exam-time" /></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Room"><input className={inputClass()} value={form.room} onChange={(e) => setForm({ ...form, room: e.target.value })} placeholder="Library 204" data-testid="input-exam-room" /></Field><Field label="Subject"><select className={inputClass()} value={form.subjectId || ''} onChange={(e) => setForm({ ...form, subjectId: e.target.value ? Number(e.target.value) : undefined })} data-testid="select-exam-subject"><option value="">No subject</option>{subjects.data?.map((subject) => <option value={subject.id} key={subject.id}>{subject.name}</option>)}</select></Field></div><Field label="Notes"><textarea className={`${inputClass()} min-h-24 resize-y`} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="Topics, materials, or a note to future you" data-testid="textarea-exam-notes" /></Field><Button type="submit" className="w-full" disabled={create.isPending || update.isPending} testId="button-save-exam"><Check size={16} /> Save exam</Button></form></Modal>}</div>;
}

function StudyPage() {
  const sessions = useGetStudySessions(); const subjects = useGetSubjects(); const create = useCreateStudySession(); const qc = useQueryClient(); const [form, setForm] = useState({ date: todayISO(), minutes: 45, focus: '', subjectId: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: { date: form.date, minutes: Number(form.minutes), focus: form.focus, subjectId: form.subjectId ? Number(form.subjectId) : undefined } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetStudySessionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setForm({ date: todayISO(), minutes: 45, focus: '', subjectId: '' }); } }); };
  const total = sessions.data?.reduce((sum, item) => sum + item.minutes, 0) || 0;
  if (sessions.isLoading) return <LoadingPage />; if (sessions.isError) return <QueryError retry={() => sessions.refetch()} />;
  return <div className="space-y-7"><PageHeading eyebrow="Attention is a practice" title="Study log" detail="Record the sessions that count, including the imperfect ones. Momentum loves evidence." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl border bg-[hsl(var(--primary))] p-6 text-primary-foreground"><div className="flex items-center gap-2 text-[hsl(var(--accent))]"><Zap size={18} /><span className="text-xs font-bold uppercase tracking-[.15em]">This week</span></div><p className="mt-8 font-display text-6xl font-semibold">{total}<span className="ml-2 text-2xl text-[hsl(var(--sidebar-foreground)/.55)]">min</span></p><p className="mt-2 text-sm text-[hsl(var(--sidebar-foreground)/.66)]">{sessions.data?.length || 0} focused sessions logged</p><div className="mt-8 h-2 overflow-hidden rounded-full bg-[hsl(var(--sidebar-foreground)/.14)]"><div className="h-full rounded-full bg-[hsl(var(--accent))]" style={{ width: `${Math.min((total / 600) * 100, 100)}%` }} /></div><p className="mt-2 text-xs text-[hsl(var(--sidebar-foreground)/.5)]">{Math.max(0, 600 - total)} minutes to a 10-hour week</p></div><div className="rounded-2xl border bg-card p-6"><div className="flex items-center gap-2"><Clock3 size={18} className="text-[hsl(var(--destructive))]" /><h2 className="font-display text-2xl font-semibold">Log a session</h2></div><form onSubmit={submit} className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Date"><input required type="date" className={inputClass()} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} data-testid="input-study-date" /></Field><Field label="Minutes"><input required type="number" min="1" className={inputClass()} value={form.minutes} onChange={(e) => setForm({ ...form, minutes: Number(e.target.value) })} data-testid="input-study-minutes" /></Field><div className="sm:col-span-2"><Field label="What did you focus on?"><input required className={inputClass()} value={form.focus} onChange={(e) => setForm({ ...form, focus: e.target.value })} placeholder="Flashcards for memory models" data-testid="input-study-focus" /></Field></div><Field label="Subject"><select className={inputClass()} value={form.subjectId} onChange={(e) => setForm({ ...form, subjectId: e.target.value })} data-testid="select-study-subject"><option value="">General study</option>{subjects.data?.map((subject) => <option value={subject.id} key={subject.id}>{subject.name}</option>)}</select></Field><div className="flex items-end"><Button type="submit" className="w-full" disabled={create.isPending} testId="button-save-study"><Plus size={16} /> {create.isPending ? 'Saving…' : 'Save session'}</Button></div></form></div></div><div className="rounded-2xl border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">A record of showing up</p><h2 className="mt-1 font-display text-2xl font-semibold">Recent sessions</h2></div><span className="font-data text-xs text-muted-foreground">{sessions.data?.length || 0} total</span></div>{sessions.data?.length ? <div className="mt-5 divide-y">{sessions.data.slice(0, 12).map((session) => <div key={session.id} className="flex items-center gap-4 py-4" data-testid={`study-session-${session.id}`}><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--accent)/.18)] font-data text-xs font-semibold">{session.minutes}m</div><div className="min-w-0 flex-1"><p className="font-semibold">{session.focus}</p><p className="mt-1 text-xs text-muted-foreground">{session.subjectName || 'General study'} · {formatDate(session.date)}</p></div><TrendingUp size={17} className="text-[hsl(var(--destructive))]" /></div>)}</div> : <div className="mt-4"><EmptyState icon={Clock3} title="Your first session is waiting" detail="Even 20 minutes is useful data. Log what you do and build from there." /></div>}</div></div>;
}

function AnalyticsPage() {
  const analytics = useGetAnalytics();
  if (analytics.isLoading) return <LoadingPage />; if (analytics.isError || !analytics.data) return <QueryError retry={() => analytics.refetch()} />;
  const data = analytics.data;
  const maxStudy = Math.max(...data.weeklyStudy.map((item) => item.minutes), 1); const maxProductivity = Math.max(...data.productivityByWeek.map((item) => item.score), 1);
  return <div className="space-y-7"><PageHeading eyebrow="Patterns, not pressure" title="Analytics" detail="Use the shape of your semester to decide what deserves your attention next." /><div className="grid gap-5 lg:grid-cols-2"><ChartCard title="Study minutes" detail="Your weekly focus time"><div className="flex h-56 items-end gap-3 pt-8">{data.weeklyStudy.length ? data.weeklyStudy.map((item) => <div className="flex min-w-0 flex-1 flex-col items-center gap-2" key={item.label} data-testid={`chart-study-${item.label}`}><span className="font-data text-[10px] text-muted-foreground">{item.minutes}</span><div className="flex h-40 w-full items-end"><div className="w-full rounded-t-lg bg-[hsl(var(--primary))] transition-all hover:bg-[hsl(var(--destructive))]" style={{ height: `${Math.max(5, (item.minutes / maxStudy) * 100)}%` }} /></div><span className="truncate text-[10px] text-muted-foreground">{item.label}</span></div>) : <p className="text-sm text-muted-foreground">Study data will build here.</p>}</div></ChartCard><ChartCard title="Productivity trend" detail="Your weekly score"><div className="flex h-56 items-end gap-3 pt-8">{data.productivityByWeek.length ? data.productivityByWeek.map((item) => <div className="flex min-w-0 flex-1 flex-col items-center gap-2" key={item.label} data-testid={`chart-productivity-${item.label}`}><span className="font-data text-[10px] text-muted-foreground">{item.score}%</span><div className="flex h-40 w-full items-end"><div className="w-full rounded-t-lg bg-[hsl(var(--accent))] transition-all hover:bg-[hsl(var(--destructive))]" style={{ height: `${Math.max(5, (item.score / maxProductivity) * 100)}%` }} /></div><span className="truncate text-[10px] text-muted-foreground">{item.label}</span></div>) : <p className="text-sm text-muted-foreground">Productivity data will build here.</p>}</div></ChartCard></div><div className="grid gap-5 lg:grid-cols-2"><ChartCard title="Attendance by subject" detail="Where consistency is strongest"><div className="mt-5 space-y-4">{data.attendanceBySubject.length ? data.attendanceBySubject.map((item) => <div key={item.label} data-testid={`metric-attendance-${item.label}`}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.label}</span><span className="font-data text-xs">{Math.round(item.percentage)}%</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-[hsl(var(--destructive))]" style={{ width: `${item.percentage}%` }} /></div></div>) : <p className="text-sm text-muted-foreground">Attendance data will build here.</p>}</div></ChartCard><ChartCard title="Task completion" detail="How work moves through your week"><div className="mt-5 space-y-4">{data.taskCompletion.length ? data.taskCompletion.map((item) => <div key={item.label} className="flex items-center gap-4" data-testid={`metric-task-${item.label}`}><span className="w-24 text-sm font-semibold">{item.label}</span><div className="h-3 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${item.value}%` }} /></div><span className="font-data text-xs text-muted-foreground">{item.value}%</span></div>) : <p className="text-sm text-muted-foreground">Task data will build here.</p>}</div></ChartCard></div></div>;
}
function ChartCard({ title, detail, children }: { title: string; detail: string; children: ReactNode }) { return <div className="rounded-2xl border bg-card p-6"><h2 className="font-display text-2xl font-semibold">{title}</h2><p className="mt-1 text-sm text-muted-foreground">{detail}</p>{children}</div>; }

function ProfilePage() {
  const { data: student, isLoading, isError, refetch } = useGetCurrentStudent(); const update = useUpdateProfile(); const logout = useLogout(); const [, setLocation] = useLocation(); const [editing, setEditing] = useState(false); const [form, setForm] = useState<ProfileUpdate>({});
  if (isLoading) return <LoadingPage />; if (isError || !student) return <QueryError retry={() => refetch()} />;
  const startEdit = () => { setForm({ name: student.name, college: student.college || '', course: student.course || '', year: student.year || undefined }); setEditing(true); };
  const submit = (event: FormEvent) => { event.preventDefault(); update.mutate({ data: form }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetCurrentStudentQueryKey() }); setEditing(false); } }); };
  return <div className="space-y-7"><PageHeading eyebrow="The person behind the progress" title="Profile" detail="Keep the basics current so this space continues to feel like yours." action={<Button variant="secondary" onClick={startEdit} testId="button-edit-profile"><Pencil size={16} /> Edit profile</Button>} /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl border bg-[hsl(var(--primary))] p-7 text-primary-foreground"><span className="flex h-20 w-20 items-center justify-center rounded-3xl bg-[hsl(var(--accent))] font-display text-3xl font-semibold text-[hsl(var(--accent-foreground))]">{initials(student.name)}</span><h2 className="mt-6 font-display text-3xl font-semibold">{student.name}</h2><p className="mt-2 text-sm text-[hsl(var(--sidebar-foreground)/.65)]">{student.email}</p><div className="mt-8 border-t border-[hsl(var(--sidebar-foreground)/.16)] pt-5"><p className="text-xs uppercase tracking-[.14em] text-[hsl(var(--sidebar-foreground)/.48)]">Current focus</p><p className="mt-2 font-semibold">{student.course || 'Add your course'} {student.year ? `· Year ${student.year}` : ''}</p><p className="mt-1 text-sm text-[hsl(var(--sidebar-foreground)/.6)]">{student.college || 'Add your college'}</p></div></div><div className="rounded-2xl border bg-card p-7"><div className="grid gap-6 sm:grid-cols-2"><Info label="Email" value={student.email} /><Info label="College" value={student.college || 'Not added'} /><Info label="Course" value={student.course || 'Not added'} /><Info label="Year" value={student.year ? `Year ${student.year}` : 'Not added'} /></div><div className="mt-8 border-t pt-6"><Button variant="danger" onClick={() => logout.mutate(undefined, { onSuccess: () => setLocation('/login') })} disabled={logout.isPending} testId="button-profile-logout"><LogOut size={16} /> Sign out of Attendex</Button></div></div></div>{editing && <Modal title="Edit your profile" onClose={() => setEditing(false)}><form onSubmit={submit} className="mt-6 space-y-4"><Field label="Name"><input required className={inputClass()} value={form.name || ''} onChange={(e) => setForm({ ...form, name: e.target.value })} data-testid="input-profile-name" /></Field><Field label="College"><input className={inputClass()} value={form.college || ''} onChange={(e) => setForm({ ...form, college: e.target.value })} data-testid="input-profile-college" /></Field><Field label="Course"><input className={inputClass()} value={form.course || ''} onChange={(e) => setForm({ ...form, course: e.target.value })} data-testid="input-profile-course" /></Field><Field label="Year"><input type="number" min="1" max="8" className={inputClass()} value={form.year || ''} onChange={(e) => setForm({ ...form, year: e.target.value ? Number(e.target.value) : undefined })} data-testid="input-profile-year" /></Field><Button type="submit" className="w-full" disabled={update.isPending} testId="button-save-profile"><Check size={16} /> Save changes</Button></form></Modal>}</div>;
}
function Info({ label, value }: { label: string; value: string }) { return <div><p className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold" data-testid={`text-profile-${label.toLowerCase()}`}>{value}</p></div>; }

function ProtectedRoutes() {
  return <Shell><Switch><Route path="/" component={DashboardPage} /><Route path="/subjects" component={SubjectsPage} /><Route path="/tasks" component={TasksPage} /><Route path="/exams" component={ExamsPage} /><Route path="/study" component={StudyPage} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/profile" component={ProfilePage} /><Route component={NotFound} /></Switch></Shell>;
}
function Router() {
  const [location, setLocation] = useLocation();
  const auth = location === '/login' || location === '/signup' || location === '/forgot-password';
  const session = useGetCurrentStudent({ query: { enabled: !auth, retry: false, queryKey: getGetCurrentStudentQueryKey() } });
  useEffect(() => {
    if (!auth && !session.isLoading && (session.isError || !session.data)) setLocation('/login');
  }, [auth, session.data, session.isError, session.isLoading, setLocation]);
  if (!auth && session.isLoading) return <LoadingPage />;
  if (!auth && (session.isError || !session.data)) return null;
  return <ErrorBoundary resetKey={location}>{auth ? <Switch><Route path="/login" component={LoginPage} /><Route path="/signup" component={SignupPage} /><Route path="/forgot-password" component={ForgotPasswordPage} /><Route component={NotFound} /></Switch> : <ProtectedRoutes />}</ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></QueryClientProvider>;
}
export default App;